 Object.keys(sc).forEach(function(nm){ p.laws[nm]=sc[nm].score; S.law[nm]=sc[nm].score; });
 p.intake.done=Object.keys(sc);
 if(p.intake.done.length===21 && !p.intake.completedAt) p.intake.completedAt=new Date().toISOString();
