/* ============================================================
   THE PATH.

   scanStory already records `at`, the character offset of every hit, and
   sorts the hits by it. parseStory then collapsed everything into per band
   totals, so the route a sentence takes through the body was computed once
   per parse and thrown away. This keeps it.

   Every step sits at a measured position: the centroid of that seat's own
   traced nerve branches, SEATXY. No invented anatomy. What the path adds is
   order, direction and distance, which the totals cannot carry.

   It is a record, not an input. applyStory does not read it and no number in
   the app moves because of it. That is deliberate: the claim it encodes is
   not measured yet, and an unmeasured claim must not reach the arithmetic.
   ============================================================ */

/* Where a named charge sits. Mirrors CHG2SEAT, which is the app's existing
   answer, lowercased to the seat keys the artwork uses. Three charges have no
   entry there: silence and doubt are routed the way CHG2FET already routes
   them, through apathy and shock. joy is coherent and places nothing. */
var PATHSEAT={fear:'root',anger:'solar',shame:'sacral',disgust:'sacral',
 apathy:'throat',shock:'eye',sadness:'heart',grief:'heart',surprise:'heart',
 anticipation:'solar',anxiety:'solar',pride:'crown',guilt:'sacral',
 craving:'sacral',separation:'crown',silence:'throat',doubt:'eye',joy:null};
var PATHMAX=28;                       /* the largest charged amount in LEX */

/* Match precedence, and the reason it is written down rather than inherited.
   scanStory adds phrases, then LEX words, then adjectives, and sorts by
   offset. Sort is stable, so equal offsets keep that insertion order, which
   means the route silently depended on the order of three loops. Stating the
   precedence here makes the path a property of the text instead. */
var PATHRANK={phrase:0, word:1, adj:2};

function seatOf(h){
 if(h.kind==='adj') return PATHSEAT[h.charge]||null;
 if(!h.band||h.band==='coherent') return null;
 return K2BAND[h.band]?h.band:null;}

/* A step is a word occurrence, not a lexicon match. One word can match a
   phrase, a LEX entry and an adjective at once, and those are the same event
   in the body, not three. The occurrence keeps every seat it names, primary
   first, because a word reaching two places is the thing being recorded. */
function pathOf(hits){
 var byAt={}, order=[];
 hits.forEach(function(h){
  if(byAt[h.at]===undefined){byAt[h.at]=[];order.push(h.at);}
  byAt[h.at].push(h);});
 order.sort(function(a,b){return a-b;});

 var steps=order.map(function(at,i){
  var g=byAt[at].slice().sort(function(a,b){
   var r=PATHRANK[a.kind]-PATHRANK[b.kind];
   if(r)return r;
   return String(a.t)<String(b.t)?-1:String(a.t)>String(b.t)?1:0;});
  var seats=[], seen={};
  g.forEach(function(h){var k=seatOf(h);
   if(k&&!seen[k]){seen[k]=1;seats.push(k);}});
  /* the amount comes from whichever match carries one. an adjective names the
     charge without scoring it, and reading that as zero made the adjective the
     minimum of every path it appeared in. */
  var scored=g.filter(function(h){return h.amt!=null;});
  var amt=scored.length?scored.reduce(function(a,h){
   return Math.abs(h.amt)>Math.abs(a)?h.amt:a;},scored[0].amt):null;
  var k=seats[0]||null, xy=k?SEATXY[k]:null;
  return {i:i, at:at, word:g[0].t, kind:g[0].kind,
   seat:k, band:k?K2BAND[k]:null, seats:seats,
   x:xy?xy.x:null, y:xy?xy.y:null,
   amt:amt, depth:amt!=null?clamp(amt/PATHMAX,0,1):null,
   coherent:g.some(function(h){return h.band==='coherent';})};});

 var on=steps.filter(function(s){return s.seat;});
 var sc=on.filter(function(s){return s.amt!=null;});
 var span=0, net=0, drop=0, rise=0, dwell=null, kink=null, floor=null;
 if(on.length){
  for(var j=1;j<on.length;j++){
   var dx=on[j].x-on[j-1].x, dy=on[j].y-on[j-1].y;
   span+=Math.sqrt(dx*dx+dy*dy);
   if(dy>drop)drop=dy; if(dy<rise)rise=dy;}
  net=on[on.length-1].y-on[0].y;      /* positive is downward, toward root */
  var tal={};on.forEach(function(s){tal[s.seat]=(tal[s.seat]||0)+1;});
  dwell=on.reduce(function(a,s){return tal[s.seat]>tal[a]?s.seat:a;},on[0].seat);}
 /* The kink. parseStory sorts by susceptibility and takes the top, which is to
    say the app already assumed the block sits at the highest charge. Nobody
    ruled that. Both ends are reported so it can be ruled from data rather than
    from a sort order. */
 if(sc.length){
  kink =sc.reduce(function(a,s){return s.amt>a.amt?s:a;},sc[0]);
  floor=sc.reduce(function(a,s){return s.amt<a.amt?s:a;},sc[0]);}

 function end(s){return s?{seat:s.seat,word:s.word,amt:s.amt,i:s.i}:null;}
 return {steps:steps, located:on.length, scored:sc.length,
  span:Math.round(span*100)/100, net:Math.round(net*100)/100,
  drop:Math.round(drop*100)/100, rise:Math.round(rise*100)/100,
  dwell:dwell, start:on.length?on[0].seat:null, end:on.length?on[on.length-1].seat:null,
  kink:end(kink), floor:end(floor)};}

function parseStory(text){
 var hits=scanStory(text), byBand={}, byChg={}, imprints=[];
 hits.forEach(function(h){
  if(h.band&&h.band!=='coherent'){ byBand[h.band]=(byBand[h.band]||0)+h.amt; }
  if(h.charge){ byChg[h.charge]=(byChg[h.charge]||0)+1; }});
 var wanted={}; Object.keys(byChg).forEach(function(c){var f=CHG2FET[c]; if(f)wanted[f]=true;});
 var anyNamed=Object.keys(wanted).length>0;
 Object.keys(byBand).forEach(function(k){
  var bn=K2BAND[k]; if(!bn) return;
  var all=W.filter(function(n){return n.b===bn&&n.cf;});
  /* Band says WHERE, the adjective says WHAT. But a named fetter only governs
     a band it actually occupies. The original accepted any non-empty match, so
     one Shame address at the heart was enough to route the whole heart band --
     including everything the despair idioms carried -- onto Shame, and grief
     was filed as shame. A named fetter now has to hold at least a quarter of
     the band, otherwise the band's own modal fetter is the better read. */
  var seg=anyNamed? all.filter(function(n){return wanted[n.cf];}) : [];
  if(seg.length < all.length*0.25){
   var tally={}; all.forEach(function(n){tally[n.cf]=(tally[n.cf]||0)+1;});
   var modal=Object.keys(tally).sort(function(a,b){return tally[b]-tally[a];})[0];
   var mseg=all.filter(function(n){return n.cf===modal;});
   /* keep whichever reading is better represented at this seat */
   if(mseg.length>seg.length) seg=mseg;
   if(!seg.length) seg=all;}
  seg=seg.sort(function(a,b){return (b.susc||1)-(a.susc||1);});
  if(!seg.length) return;
  /* the intensity curve is 0-30ish. normalise to a 0-10 charge delta. */
  var total=Math.min(10,byBand[k]/3), share=total/Math.min(4,seg.length);
  seg.slice(0,4).forEach(function(n){
   imprints.push({node:n.i, name:n.k, band:bn, fetter:n.cf,
    amt:Math.round(share*10)/10, from:k});});});
 var nm={}; Object.keys(byChg).forEach(function(c){
  var f=CHG2FET[c]; if(f) nm[f]=(nm[f]||0)+byChg[c];});
 var named=Object.keys(nm).sort(function(a,b){return nm[b]-nm[a];});
 return {hits:hits, bands:byBand, charges:byChg, named:named, weights:nm, imprints:imprints,
  path:pathOf(hits),
  words:hits.filter(function(h){return h.kind!=='adj';}).length};}
function applyStory(text){
 var p=parseStory(text), touched={};
 p.imprints.forEach(function(im){ var f=im.fetter; if(!f) return;
  touched[f]=(touched[f]||0)+im.amt;});
 /* an adjective sharpens which fetter; repeated mentions weigh more */
 p.named.forEach(function(f,i){ touched[f]=(touched[f]||0)+0.8/(1+i*0.5); });
 Object.keys(touched).forEach(function(f){
  S.charge[f]=clamp((S.charge[f]||0)+touched[f]*0.35,0,10);});
 /* the coherent words pull the other way */
 var calm=p.hits.filter(function(h){return h.band==='coherent';})
  .reduce(function(a,h){return a+Math.abs(h.amt);},0);
 if(calm)CHARGES.forEach(function(c){S.charge[c]=clamp(S.charge[c]-calm/140,0,10);});
 return {parsed:p, applied:touched};}

/* ============================================================
   ENERGETICS. Pure functions of date, time and place. Nothing else
   is stored, so a sixth system costs nothing.
   ============================================================ */
function sunSign(d){
 var p=d.split('-'), m=+p[1], day=+p[2];
 for(var j=0;j<ZSIGN.length;j++){
  var a=ZSIGN[j], b=ZSIGN[(j+1)%12];
  if((m===a[0]&&day>=a[1])||(m===b[0]&&day<b[1]))
   return {nm:a[2], el:a[3], mode:a[4]};}
 return {nm:ZSIGN[11][2], el:ZSIGN[11][3], mode:ZSIGN[11][4]};}
function moonSign(bt){
 var d=new Date(bt.d+'T00:00:00Z');
 var days=Math.floor(d.getTime()/86400000);
 var i=(((days%27.32)+27.32)%27.32)/27.32;      /* pre-1970 births give negative days */
 var k=Math.floor(i*12); k=((k%12)+12)%12;
 return ZSIGN[k];}
function risingSign(bt){
 var sun=sunSign(bt.d), si=0;
 ZSIGN.forEach(function(z,k){if(z[2]===sun.nm)si=k;});
 var h=+bt.t.split(':')[0]+(+bt.t.split(':')[1])/60;
 var off=Math.floor(((h-6+24)%24)/2);
 return ZSIGN[(((si+off)%12)+12)%12];}
function lifePath(d){
 var v=d.replace(/-/g,'').split('').reduce(function(a,c){return a+ +c;},0);
 while(v>9&&v!==11&&v!==22&&v!==33)
  v=String(v).split('').reduce(function(a,c){return a+ +c;},0);
 return v;}
function masterNumber(bt){var lp=lifePath(bt.d);return (lp===11||lp===22||lp===33)?lp:null;}
function chineseElement(y){ return CELEM[y%10]; }
function hdOf(b){
 var h=+b.t.split(':')[0];
 return {type:HDTYPE[(h+lifePath(b.d))%5],
  authority:['emotional','sacral','splenic','ego','self-projected','lunar'][(h+3)%6]};}
function geneKey(b){var day=+b.d.split('-')[2];return {gate:((day*3)%64)+1, line:(day%6)+1};}
function spiritual(name){
 var bt=BIRTH[name]; if(!bt) return null;
 var sun=sunSign(bt.d), mn=moonSign(bt), rs=risingSign(bt), y=+bt.d.split('-')[0];
 return {sun:sun.nm, sunEl:sun.el, sunMode:sun.mode, moon:mn[2], moonEl:mn[3],
  rising:rs[2], risingEl:rs[3], chinese:CHINESE[y%12], celem:chineseElement(y),
  lp:lifePath(bt.d), master:masterNumber(bt), hd:hdOf(bt), gk:geneKey(bt), birth:bt,
  root:ELEM2ROOT[sun.el], mode:MODE2NOTE[sun.mode], lpMean:LPMEAN[lifePath(bt.d)]||''};}
/* CONVERGENCE. where independent systems agree, that is the signal.
   where they disagree the instrument says so rather than picking a winner. */
function converge(name,r){
 var e=spiritual(name); if(!e) return null;
 var agree=[],differ=[];
 var rootNow=(DOMAINS[S.doms[0]]||{}).r||'';
 if(e.root===rootNow) agree.push('birth element '+e.sunEl+' and your root domain both read '+e.root);
 else differ.push('birth element points '+e.root+', your domain runs '+rootNow);
 var archNow=(ARCH[r.pi]||{}).nm||'';
 if(LP2ARCH[e.lp]===archNow) agree.push('life path '+e.lp+' and your first archetype both read '+archNow);
 else differ.push('life path '+e.lp+' reads '+(LP2ARCH[e.lp]||'unmapped')+', you run '+archNow);
 var initiating=(e.sunMode==='cardinal');
 if(initiating===!!r.benign) agree.push('birth mode '+e.sunMode+' matches a field that is '
   +(r.benign?'expanding':'contracting'));
 else differ.push('birth mode '+e.sunMode+' against a field that is '+(r.benign?'expanding':'contracting'));
 var hdOpen=(e.hd.type==='Generator'||e.hd.type==='Manifesting Generator');
 if(hdOpen===(r.CQ>=50)) agree.push(e.hd.type+' and a field at CQ '+Math.round(r.CQ)+' point the same way');
 else differ.push(e.hd.type+' against a field at CQ '+Math.round(r.CQ));
 return {e:e, agree:agree, differ:differ,
  score:Math.round(agree.length/(agree.length+differ.length)*100)};}


/* ============================================================
   THE SEED. A four letter type is the ego's own account of
   itself. It is not a reading, so this module never claims to
   have detected one: the person states it, and it is used to
   put charge on the nine axes so a new field is not empty.

   It is built from four additive terms, not sixteen written
   patterns. Sixteen patterns would be sixteen assertions about
   people, each unarguable. Four terms are four assertions, each
   of which can be argued, and the sixteen results follow.

   Every term moves charge only. It never touches a law, a gate
   or a domain, because those are measured: the laws by the 63
   questions, the gates by what a person actually writes. A seed
   that wrote those would be putting words in their mouth.
   ============================================================ */

/* the four axes of the type, and what each pole does to the body.
   each entry is a child fetter and the charge added, on the 0 to 10
   scale, against a blank field's 3. */
const SEED16={
 /* outward against inward discharge. the one term the engine measures
    directly, through balance(), so it is the term to trust most. */
 E:{Anger:0.8, Anticipation:0.8, Surprise:0.5, Fear:-0.5, Sad:-0.5},
 I:{Anger:-0.5, Anticipation:-0.4, Surprise:-0.4, Fear:0.6, Sad:0.5},
 /* where attention sits. forward and pattern seeking against present
    and concrete. anticipation is the forward lean, shock is what a
    surprise costs someone who was not looking ahead. */
 N:{Anticipation:0.8, Surprise:0.6, Apathy:-0.3, Shock:-0.3},
 S:{Anticipation:-0.6, Shock:0.4, Disgust:0.3, Surprise:-0.3},
 /* what a decision is made of. a governed read carries less affect and
    more standard. an affective read carries more worth and more grief. */
 T:{Shame:-0.8, Sad:-0.6, Disgust:0.5},
 F:{Shame:0.6, Sad:0.6, Disgust:-0.4},
 /* whether the thing is closed or left open. a closed stance holds a
    standard and stops anticipating. an open one keeps the loop running. */
 J:{Disgust:0.6, Anticipation:-0.5, Fear:-0.3},
 P:{Anticipation:0.6, Fear:0.3, Disgust:-0.4, Apathy:0.2}};

const TYPE16=['INTJ','INTP','ENTJ','ENTP','INFJ','INFP','ENFJ','ENFP',
 'ISTJ','ISFJ','ESTJ','ESFJ','ISTP','ISFP','ESTP','ESFP'];

function seedValid(t){return TYPE16.indexOf(String(t||'').toUpperCase())>=0;}

/* the axes a type seeds, as absolute charges. base 3, the same floor a
   blank profile carries, so a seeded field and an unseeded one are on
   one scale. */
function seedAxes(type){
 var t=String(type||'').toUpperCase(), out={};
 CHARGES.forEach(function(c){out[c]=3;});
 if(!seedValid(t))return out;
 t.split('').forEach(function(letter){
  var d=SEED16[letter]; if(!d)return;
  Object.keys(d).forEach(function(c){
   if(out[c]!=null)out[c]=Math.max(0,Math.min(10,out[c]+d[c]));});});
 CHARGES.forEach(function(c){out[c]=Math.round(out[c]*10)/10;});
 return out;}

/* write the seed onto a profile. it records what it wrote, so the
   product can say later how much of the field is still the seed and
   how much the person has moved it. seeding twice re-seeds from the
   base rather than compounding. */
function seedApply(p,type){
 if(!p||!seedValid(type))return null;
 var ax=seedAxes(type);
 CHARGES.forEach(function(c){
  p.axes[c]=p.axes[c]||{held:3,opp:0};
  p.axes[c].held=ax[c];});
 p.seed={type:String(type).toUpperCase(), at:new Date().toISOString(), axes:ax};
 return p.seed;}

function seedClear(p){ if(p)p.seed=null; return p; }

/* HOW MUCH IS STILL THE SEED. the distance the axes have travelled from
   where the seed put them, against the distance the seed itself moved
   them from a blank field. 1 means untouched since seeding, 0 means the
   person's own input now accounts for all of it. It is a measurement,
   not a countdown: charge moved back toward the seed raises it again. */
function seedShare(p){
 if(!p||!p.seed||!p.seed.axes)return 0;
 var seeded=0, moved=0;
 CHARGES.forEach(function(c){
  var s=p.seed.axes[c]!=null?p.seed.axes[c]:3;
  var now=(p.axes[c]&&p.axes[c].held!=null)?p.axes[c].held:3;
  seeded+=Math.abs(s-3);
  moved+=Math.abs(now-s);});
 if(seeded+moved<=0)return 0;
 return Math.round(seeded/(seeded+moved)*100)/100;}

/* ============================================================
   THE FRONT DOOR. Input, throughput, output, and nothing else.

     input(profile, opts)   one profile in. it is the only input.
     throughput(profile)    the chain, in the one order it runs in.
     output(profile)        the field back out as schema, plus the reading.
     read(profile, opts)    all three in one call. what callers want.

   Why this module exists. The chain underneath runs on shared field
   state: S, DOMAIN, VERPMIX, LEANMIX. compute() takes no arguments and
   reads all four. That was the ported design and it stays, because the
   ruling was port and not rebuild. So this is the only place permitted
   to touch that state. It touches it in one fixed order, and it zeroes
   what accumulates. Call read() twice on one profile and the numbers
   come back identical. That was not true of the chain on its own.
   ============================================================ */

/* ---------- INPUT ----------
   The profile is the only input. A story that has not been applied yet
   is the one thing not in it, so it comes separately and is applied once.
   p.story.entries is a log of stories already baked into p.axes by a
   previous save. Replaying it here would double count, so it is not read. */
function input(prof,opts){
 var p=prof||blankProfile('unnamed'), o=opts||{};
 loadProfile(p);            /* soul, nine axes, laws, gate evidence. builds the soul */
 if(p.intake&&p.intake.answers)iqApply(p);    /* a measured law beats the default 6 */
 if(o.story){                                 /* new text, not yet in the axes */
  applyStory(o.story); verpApply(o.story); leanApply(o.story);}
 return p;}

/* ---------- THROUGHPUT ----------
   The profile is passed only so accuracy can report against it. Every
   number here comes off the field that input() placed. */
function throughput(prof){
 var r=compute();
 r.accuracy  = accuracy(r,prof);
 r.gates     = verpRead();
 r.lean      = leanRead(r);
 r.expression= exprRead();
 r.sab33     = sab33Detect();
 return r;}

/* ---------- OUTPUT ----------
   Two things come out. The profile, written back in schema shape so it
   can be stored or handed to SOURCE. And a snapshot, which is derived
   only and is what Analytics plots. */
function output(prof){
 return saveProfile(prof);}

/* ---------- the whole door ----------
   opts.story   text to apply once before computing
   opts.write   true to write the field back into the profile as well */
function read(prof,opts){
 var o=opts||{}, p=input(prof,o), r=throughput(p);
 if(o.write)output(p);
 return {profile:p, reading:r, snapshot:snapshot(p)};}

/* ============================================================
   The engine is DOM free. In a browser these are globals on the
   concatenated script. In node the same file is requireable, so the
   engine can be tested headlessly and shared with Atuned through the
   one profile object the schema contract defines.
   ============================================================ */
if(typeof module!=='undefined'&&module.exports){
 module.exports={
  /* data */      NODES:NODES, SAB_LIB:SAB_LIB, HCX_LIB:HCX_LIB, SAB33:SAB33, SAB_PI:SAB_PI, GATEGLYPH:GATEGLYPH,
                  APC:APC, APC_REL:APC_REL, APC_EMB:APC_EMB, INFER_NOUN:INFER_NOUN,
                  SABAUTH:SABAUTH, ARCH18:ARCH18, CHILD:CHILD, CHARGES:CHARGES,
                  DOMAINS:DOMAINS, ARCH:ARCH, SI:SI, SINAMES:SINAMES, MASKS:MASKS,
                  BANDS:BANDS, PAL:PAL, ROOTD:ROOTD, ROOTCOL:ROOTCOL, AFFIN:AFFIN,
                  PRACTICE:PRACTICE, EXPR:EXPR, PMBANDS:PMBANDS, FLOWSEAT:FLOWSEAT,
                  PAINREG:PAINREG, PEOPLE:PEOPLE, LAWSET:LAWSET, BIRTH:BIRTH,
                  LEX:LEX, ADJ2CHG:ADJ2CHG, PHRASES:PHRASES, VERP:VERP,
                  NERVEBR:NERVEBR, BODYPATH:BODYPATH, TAB:TAB,
  /* indexes */   W:W, BY:BY, ALL_SAB:ALL_SAB, S:S,
  /* soul */      buildSoul:buildSoul, affinity:affinity, bandIg:bandIg,
  /* engine */    compute:compute, suscAll:suscAll, balance:balance, OUTWARD:OUTWARD, INWARD:INWARD,
  /* seed */      TYPE16:TYPE16, SEED16:SEED16, seedAxes:seedAxes, seedApply:seedApply,
                  seedClear:seedClear, seedShare:seedShare, seedValid:seedValid, accuracy:accuracy, sab33Detect:sab33Detect,
                  sabLevels:sabLevels, exprFill:exprFill, exprRead:exprRead,
  /* gates */     verpScan:verpScan, verpApply:verpApply, verpFactor:verpFactor,
                  verpRead:verpRead, verpShare:verpShare,
                  leanScan:leanScan, leanApply:leanApply, leanRead:leanRead,
                  VERPMIX:VERPMIX, LEANMIX:LEANMIX,
  /* the door */  read:read, input:input, throughput:throughput, output:output,
                  gatesClear:gatesClear, gatesLoad:gatesLoad, gatesSave:gatesSave,
  /* schema */    blankProfile:blankProfile, loadProfile:loadProfile,
                  saveProfile:saveProfile, snapshot:snapshot,
                  pExport:pExport, pImport:pImport, validateProfile:validateProfile, importError:importError,
                  meterRun:meterRun, meterRead:meterRead, meterKey:meterKey, MARKERS:MARKERS, PAT_PER_YEAR:PAT_PER_YEAR,
                  profiles:function(){return PROFILES;}, current:function(){return CURP;}, SCHEMA_V:SCHEMA_V,
                  bindStore:bindStore, PKEY:PKEY, pPersist:pPersist, saveState:saveState,
                  storeBound:function(){return STORE_BOUND;},
  /* intake */    iqList:iqList, iqScore:iqScore, iqApply:iqApply,
  /* sniffer */   scanStory:scanStory, parseStory:parseStory, applyStory:applyStory,
                  pathOf:pathOf, seatOf:seatOf, SEATXY:SEATXY, PATHSEAT:PATHSEAT,
  /* birth */     sunSign:sunSign, moonSign:moonSign, risingSign:risingSign,
                  lifePath:lifePath, spiritual:spiritual, converge:converge,
                  /* the rest of the module. they were reachable as browser
                     globals but absent from the contract, so nothing outside
                     a page could test them. */
                  masterNumber:masterNumber, chineseElement:chineseElement,
                  hdOf:hdOf, geneKey:geneKey,
  /* util */      clamp:clamp, leaves:(typeof leaves==='function'?leaves:null)
 };
}
